package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.FieldPosition;
import java.text.Format;
import java.text.NumberFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.util.*;
import java.util.Locale;
import org.apache.commons.math3.complex.Complex;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for ComplexFormat.parse method.
 */
public class ComplexFormat_parse_TriageGen1Test {

    private ComplexFormat complexFormat;

    @Before
    public void setUp() {
        // Default constructor uses standard formats and 'i' as imaginary character
        complexFormat = new ComplexFormat();
    }

    @Test
    public void testParse_ValidRealOnly() {
        String source = "12.5";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(0.0, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidPositiveComplex() {
        String source = "12.5+3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidNegativeComplex() {
        String source = "12.5-3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(-3.4, result.getImaginary(), 1e-10);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_WithWhitespace() {
        String source = "  12.5  +  3.4  i  ";
        // Note: The implementation parses whitespace after real and after sign.
        // However, it expects the imaginary character immediately after the imaginary number.
        // Let's test a variation that matches the logic flow.
        String sourceValid = "  12.5 + 3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(sourceValid, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
    }

    @Test
    public void testParse_InvalidReal() {
        String source = "abc+1i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidSign() {
        String source = "12.5*3.4i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // Error index should be at the start of the invalid sign '*'
        assertEquals(4, pos.getErrorIndex());
    }

    @Test
    public void testParse_InvalidImaginaryNumber() {
        String source = "12.5+abc i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidImaginaryCharacter() {
        String source = "12.5+3.4j"; // 'j' instead of 'i'
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // Error index should be at the start of the character comparison failure
        // "12.5+3.4" is index 7. 'j' is at index 7.
        assertEquals(7, pos.getErrorIndex());
    }

    @Test
    public void testParse_PartialString() {
        String source = "12.5+3.4i extra";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(12.5, result.getReal(), 1e-10);
        assertEquals(3.4, result.getImaginary(), 1e-10);
        assertEquals(8, pos.getIndex()); // Length of "12.5+3.4i"
    }

    @Test
    public void testParse_CustomImaginaryChar() {
        ComplexFormat customFormat = new ComplexFormat("j");
        String source = "1.0+2.0j";
        ParsePosition pos = new ParsePosition(0);
        Complex result = customFormat.parse(source, pos);

        assertEquals(1.0, result.getReal(), 1e-10);
        assertEquals(2.0, result.getImaginary(), 1e-10);
    }

    @Test
    public void testParse_SignWithWhitespace() {
        // Testing the branch where whitespace is parsed after the sign
        String source = "10.0 + 5.0i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = complexFormat.parse(source, pos);

        assertEquals(10.0, result.getReal(), 1e-10);
        assertEquals(5.0, result.getImaginary(), 1e-10);
    }
}
